def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def iscube(a):
    cube_root = round(abs(a) ** (1/3))
    if a < 0:
        cube_root = -cube_root
    return cube_root ** 3 == a

def solve(N):
    digit_sum = sum(int(d) for d in str(N))
    return bin(digit_sum)[2:]

def cycpattern_check(a, b):
    n = len(b)
    for i in range(n):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def even_odd_count(num):
    num = abs(num)
    even_count = 0
    odd_count = 0
    for digit in str(num):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def select_words(s, n):
    vowels = set('aeiouAEIOU')

    def count_consonants(word):
        return sum(1 for char in word if char.isalpha() and char not in vowels)

    result = []
    words = s.split()

    for word in words:
        if count_consonants(word) == n:
            result.append(word)

    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_words)

def find_max(words):
    if not words:
        return ""

    max_unique = 0
    result = ""

    for word in words:
        unique_count = len(set(word))
        if unique_count > max_unique:
            max_unique = unique_count
            result = word
        elif unique_count == max_unique and word < result:
            result = word

    return result

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def largest_smallest_integers(lst):
    max_neg = None
    min_pos = None

    for num in lst:
        if num < 0:
            if max_neg is None or num > max_neg:
                max_neg = num
        elif num > 0:
            if min_pos is None or num < min_pos:
                min_pos = num

    return (max_neg, min_pos)

