def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if 'a' <= char <= 'z':
                if (ord(char) - ord('a')) % 2 == 1:
                    count += 1
        return count

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    indexed = [(i, x) for i, x in enumerate(nums)]
    indexed.sort(key=lambda t: (digit_sum(t[1]), t[0]))
    return [x for _, x in indexed]

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift = shift % n
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

def f(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            factorial = 1
            for j in range(1, i + 1):
                factorial *= j
            result.append(factorial)
        else:
            result.append(i * (i + 1) // 2)
    return result

def vowels_count(s):
    count = 0
    vowels = set('aeiouAEIOU')
    for i, char in enumerate(s):
        if char in vowels:
            count += 1
        elif char == 'y' and i == len(s) - 1:
            count += 1
    return count

from typing import List


def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []
    result = [numbers[0]]
    for num in numbers[1:]:
        result.append(delimeter)
        result.append(num)
    return result

from collections import Counter

def common(l1: list, l2: list):
    c1 = Counter(l1)
    c2 = Counter(l2)
    return sorted(c1 & c2)
